/**
 * A minimal but valid glTF 2.0 binary (single triangle, default material), used
 * by {@link MockGenerator} as its stand-in "generated" output until World Labs
 * Atlas is wired in. Generated by `scripts` in the milestone-3 notes; edit there,
 * not here.
 */
export const SAMPLE_GLB_BASE64 =
  "";

/** The decoded sample as bytes. */
export function sampleGlb(): Buffer {
  return Buffer.from(SAMPLE_GLB_BASE64, "base64");
}
